scripts.build:
tsc --noEmit && npm run link-workspace && cpy "src/**/*.ts" "!src/**/*.test.ts" dist && renamer --find .ts --replace .d.ts "dist/**" && replace-in-file "/ *// eslint-disable-next-line [^
]+
/g" "" dist/** --isRegex && replace-in-file "/ */\* eslint-(disable|enable) [^
]+ \*/
/g" "" dist/** --isRegex && prettier --log-level=silent --write ./dist/ --ignore-path !dist/ && cpy package.json dist && json -I -f dist/package.json -e "this.types = './index.d.ts'; delete this.private; delete this.scripts" && node -e "import fs from 'node:fs'; fs.copyFileSync('README.md', 'dist/README.md'); fs.copyFileSync('../../LICENSE', 'dist/LICENSE'); fs.copyFileSync('../../COMMERCIAL_LICENSE.md', 'dist/COMMERCIAL_LICENSE.md')"
